/// <reference types="node" />
/**
 * Writes supabase/setup.sql: every migration in order, then the sample
 * catalog. One file to paste into the Supabase SQL editor on a new project.
 *
 *   npm run setup-sql
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const dir = join(__dirname, '..', 'supabase');
const migrations = readdirSync(join(dir, 'migrations'))
  .filter((f) => f.endsWith('.sql'))
  .sort();

const parts = [
  '-- Swipeshop: complete database setup for a NEW Supabase project.',
  '-- Generated by scripts/build-setup-sql.ts from supabase/migrations + supabase/seed.sql.',
  '-- Paste all of this into Supabase > SQL Editor > New query, then press Run. Run it once.',
  '',
  ...migrations.flatMap((f) => [`-- ===== migrations/${f} =====`, readFileSync(join(dir, 'migrations', f), 'utf8')]),
  '-- ===== seed.sql (sample catalog) =====',
  readFileSync(join(dir, 'seed.sql'), 'utf8'),
];

writeFileSync(join(dir, 'setup.sql'), parts.join('\n'));
console.log(`Wrote supabase/setup.sql (${migrations.length} migrations + seed)`);
